local Players = game:GetService("Players")
local player = Players.LocalPlayer or Players.PlayerAdded:Wait()
local validationUrl = "https://zyox-api.zyoxkeys.workers.dev/validate?key=pIAtBZ4bvGsN8hcLXDNE&guild=1542361223465803846&user=1524302165672202261"
local function getHwid()
  local id
  pcall(function() if gethwid then id = gethwid() end end)
  if type(id) ~= "string" or id == "" then
    pcall(function() id = game:GetService("RbxAnalyticsService"):GetClientId() end)
  end
  if type(id) ~= "string" or id == "" then return "unknown" end
  return id
end
local hwid = game:GetService("HttpService"):UrlEncode(getHwid())
local expiresAt = tonumber("1793368731674") / 1000
local function invalidateScript()
  local containers = {}
  pcall(function() if gethui then table.insert(containers, gethui()) end end)
  pcall(function() table.insert(containers, game:GetService("CoreGui")) end)
  pcall(function() table.insert(containers, player:WaitForChild("PlayerGui")) end)
  local names = {"CustomGUI", "SakuraIntro", "ZYOX_ExpiredKey", "ZYOX_ExpiredKeyError"}
  for _, container in ipairs(containers) do
    for _, name in ipairs(names) do
      pcall(function()
        local gui = container:FindFirstChild(name)
        if gui then gui:Destroy() end
      end)
    end
  end
  player:Kick("La script key expiró o fue revocada.")
end
task.delay(math.max(0, expiresAt - os.time()), function()
  invalidateScript()
end)
task.spawn(function()
  while task.wait(1) do
    local ok, body = pcall(function()
      return game:HttpGet(validationUrl .. "&hwid=" .. hwid)
    end)
    if not ok or body ~= "ok" then
      invalidateScript()
      return
    end
  end
end)
